#include "race_ai.hpp"
#include "simulation.hpp"
#include "course_ui.hpp"
#include <iostream>
#include <stdexcept>
using namespace ofo;
void need(bool b,const char*m){if(!b)throw std::runtime_error(m);}
Geometry plane(){Geometry g;g.materials.push_back({"ground"});Mesh m;m.vertices={{{-500,0,-500}},{{500,0,-500}},{{500,0,500}},{{-500,0,500}}};m.indices={0,2,1,0,3,2};g.meshes.push_back(m);return g;}
VehicleConfig car(){VehicleConfig c;c.mass=1000;c.inertia={1000,1500,1000};c.lo={-.8f,-.25f,-1.5f};c.hi={.8f,.3f,1.5f};c.ratios={3,2,1.5f,1};c.engine_torque=180;c.torque_curve={{950,1},{7000,1}};int i=0;for(auto&w:c.wheels){w.mount={(i%2?1:-1)*.7f,-.2f,(i<2?1:-1)*1.1f};w.rest=.4f;w.radius=.3f;i++;}return c;}
RaceRoute straight(){RaceRoute r;for(int i=0;i<50;i++)r.points.push_back({0,0,float(i*5)});for(int i=0;i<50;i++)r.points.push_back({80,0,float(245-i*5)});return r;}
int main(int argc,char**argv){try{
 auto b=decode_ai_behavior({{"LookAheadMin",8},{"LookAheadMax",50},{"ThrottleLimit",.8},{"BumpAggression",.3},{"NeutralBrakeTime",1.1}},{{"Racing",{{"ThrottleMax",Json::array({.7,.9})},{"TurnScale",4}}}});need(b.look_min==8&&b.look_max==50&&b.throttle==.8f&&b.brake_time==1.1f&&b.throttle_min==.7f&&b.turn_scale==4,"native named behavior and numeric array decode");
 auto r=straight();RaceAIController ai(r,b,1);AIVehiclePose p{translate({0,.5f,0}),{0,0,10}};auto cmd=ai.update(p,{p},.01f);need(cmd.throttle>0&&std::abs(cmd.steer)<.01,"straight line drives forward");p.car=translate({5,.5f,0});cmd=ai.update(p,{p},.01f);need(cmd.steer<0,"cross track steering corrects toward authored line");RaceAIController recovery(r,b,1);p={translate({0,.5f,20}),{}};bool relocated=false;for(int i=0;i<1100;i++){cmd=recovery.update(p,{p},.01f);if(cmd.recover){relocated=true;need(cmd.recovery[14]<=25,"stuck recovery remains near navigation point, never skips forward");break;}}need(relocated,"stuck navigation eventually relocates with explicit event");
 // Repeated stalls must never produce a reverse command in either mode.
 RaceAIController forward_only(r,b,2);p={translate({0,.5f,20}),{}};int recoveries=0;
 for(int i=0;i<2000;i++){cmd=forward_only.update(p,{},.01f);need(cmd.throttle>=0,"race AI never commands reverse during repeated stalls");if(cmd.recover){++recoveries;p.car=cmd.recovery;}}
 need(recoveries>=2,"repeated stalls have bounded recovery");
 RaceAIController spun(r,b,3);p={multiply(translate({0,.5f,60}),rotate_y(3.14159265f)),{0,0,-10}};relocated=false;
 for(int i=0;i<150;i++){cmd=spun.update(p,{},.01f);need(cmd.throttle==0,"wrong-heading AI brakes instead of driving backwards along the course");if(cmd.recover){need(direction(cmd.recovery,{0,0,1}).z>.99f,"wrong-heading recovery aligns with authored forward route");need(cmd.recovery[14]<=65,"wrong-heading recovery cannot skip ahead");relocated=true;break;}}
 need(relocated,"moving wrong-heading AI has bounded alignment recovery");
 // Moving backwards past an earlier point must not rewind the acquired cursor.
 RaceAIController cursor(r,b,0);p={translate({0,.5f,100}),{0,0,10}};cursor.update(p,{},.01f);p={translate({0,.5f,50}),{}};relocated=false;
 for(int i=0;i<700;i++){cmd=cursor.update(p,{},.01f);if(cmd.recover){need(cmd.recovery[14]>=100&&cmd.recovery[14]<=105,"navigation cursor keeps forward progress after backward displacement");relocated=true;break;}}
 need(relocated,"backward displacement eventually recovers at retained progress");
 RaceRoute arena;arena.derby=true;RaceAIController derby(arena,b,0);p={translate({0,.5f,0}),{}};AIVehiclePose opponent{translate({0,.5f,-20}),{}};recoveries=0;
 for(int i=0;i<1400;i++){cmd=derby.update(p,{p,opponent},.01f);need(cmd.throttle>=0,"derby AI never commands reverse during repeated stalls");if(cmd.recover){++recoveries;need(length(Vec{cmd.recovery[12],0,cmd.recovery[14]})<.01f,"derby recovery stays at current arena position");need(direction(cmd.recovery,{0,0,1}).z<-.99f,"derby recovery faces valid target");p.car=cmd.recovery;}}
 need(recoveries>=2,"derby stall recovery is bounded");
 // Straight pace must not be capped at the old 27-33m/s ceiling, and an
 // opponent ahead of the player must not keep reducing its pedal forever.
 auto fastcfg=car();fastcfg.ratios={3,2,1.3f,.8f};RaceAIController fast(r,NativeAIBehavior{},0,fastcfg),ahead_player(r,NativeAIBehavior{},0,fastcfg);
 p={translate({0,.5f,100}),{0,0,35}};auto clean=fast.update(p,{},.01f);AIVehiclePose player_behind{translate({0,.5f,40}),{0,0,10}};auto chased=ahead_player.update(p,{player_behind},.01f);
 need(clean.throttle>.6f&&clean.brake==0,"straight pace uses drivetrain capability beyond 33m/s");need(std::abs(clean.throttle-chased.throttle)<.0001f&&chased.brake==0,"player behind does not permanently slow racing AI");
 RaceRoute circle;circle.half_width=8;for(int i=0;i<100;++i){float a=i*6.2831853f/100;circle.points.push_back({30*(1-std::cos(a)),0,30*std::sin(a)});}auto drycfg=car();drycfg.mu=1;RaceAIController dry(circle,NativeAIBehavior{},0,drycfg),wet(circle,NativeAIBehavior{},0,drycfg);wet.set_grip_scale(.7f);p={translate({0,.5f,0}),{0,0,25}};auto dry_turn=dry.update(p,{},.01f),wet_turn=wet.update(p,{},.01f);
 need(dry_turn.brake>0&&dry_turn.target_speed<20,"physical curvature limit brakes for tight curve");need(wet_turn.target_speed<dry_turn.target_speed,"reduced actual tire grip lowers corner entry speed");need(dry_turn.steer>0,"interpolated pursuit follows right curve");
 // Passing and blocking remain bounded inside the authored road and cannot
 // provoke a speed limit for a car already alongside or well behind.
 RaceAIController passing(r,NativeAIBehavior{},1,fastcfg);p={translate({0,.5f,100}),{0,0,15}};AIVehiclePose slow{translate({0,.5f,113}),{0,0,6}};float previous_lane=0;for(int i=0;i<200;++i){cmd=passing.update(p,{slow},.01f);need(std::abs(cmd.lane_offset)<=3.001f&&std::abs(cmd.lane_offset-previous_lane)<=.0171f,"passing line stays bounded and changes progressively");previous_lane=cmd.lane_offset;}
 slow.car=translate({3,.5f,99});cmd=passing.update(p,{slow},.01f);need(cmd.brake==0&&cmd.throttle>.5f,"alongside traffic does not hold brake");
 auto cfg=car();Simulation shared(plane(),cfg,translate({0,1,0}));for(int k=0;k<250;k++)shared.step({});RaceOpponentConfig bot;bot.vehicle=cfg;bot.spawn=translate({0,1,9});bot.name="native test profile";bot.behavior.throttle=0;shared.set_opponents({bot},r);auto immutable=shared.state().opponents;need(immutable&&immutable->size()==1&&(*immutable)[0].name==bot.name,"initial immutable opponent pose and identity");bool impacted=false;float furthest=9;for(int k=0;k<850;k++){Input in;in.throttle=1;shared.step(in);auto s=shared.state();need(s.opponents&&s.opponents->size()==1,"one bot snapshot");const auto&o=s.opponents->front();for(float x:o.car)need(std::isfinite(x),"finite bot rigid body");furthest=std::max(furthest,o.car[14]);impacted=impacted||s.damage>0||o.damage>0;}
 need(impacted&&furthest>12,"player transfers physical impulse and damage to bot in same Bullet world");need((*immutable)[0].car[14]==9,"published opponent snapshots stay immutable");need(shared.diagnostics()["physics_worlds"]==1,"single shared physics scene");shared.set_opponents({},r);need(shared.state().opponents->empty(),"clearing bots removes rigid bodies and snapshots");
 auto world_with_prop=plane();PropDefinition prop;prop.mass=20;prop.inertia={5,5,5};prop.half={1,.5f,.5f};prop.transform=translate({0,.5f,15});world_with_prop.props.push_back(prop);Simulation prop_scene(world_with_prop,cfg,translate({-30,1,0}));RaceOpponentConfig moving=bot;moving.spawn=translate({0,1,0});moving.behavior=NativeAIBehavior{};prop_scene.set_opponents({moving},r);float bot_peak=0;for(int k=0;k<900;k++){prop_scene.step({});bot_peak=std::max(bot_peak,std::abs(prop_scene.state().opponents->front().speed));}need(bot_peak>5,"AI accelerates using player vehicle force model");need(prop_scene.diagnostics()["props"]["released"].get<int>()==1,"AI contact activates real shared-world prop");auto before_stop=std::abs(prop_scene.state().opponents->front().speed);prop_scene.set_opponent_finished(0);for(int k=0;k<300;k++)prop_scene.step({});need(std::abs(prop_scene.state().opponents->front().speed)<std::max(1.f,before_stop*.5f),"finished AI brakes physically");
 if(argc>1){Resources resources(argv[1]);const std::string stage="tracks/forest/forest1/a";auto roster=load_race_opponents(resources,1,1,1,7,stage);need(roster.size()==7&&roster[0].car_id==8&&roster[0].skin==1,"native perclass seven-car roster");need(roster[0].behavior.look_min==10&&roster[0].behavior.look_max==60,"native profile parameters consumed");auto high=load_race_opponents(resources,1,7,3,1,stage);need(high[0].vehicle.engine_torque>roster[0].vehicle.engine_torque,"native AI upgrade torque consumed");auto route=race_ai_route(race_course(resources,stage));need(route.points.size()>30,"native Catmull route used");auto geometry=load_geometry(resources,stage_geometry(stage),stage);auto player=load_vehicle(resources,3,argc>2?argv[2]:"");Simulation native(geometry,player,load_spawn(resources,stage));for(int i=0;i<200;i++)native.step({});auto initial=roster.front().spawn;native.set_opponents(roster,route);float distance=0,maxspeed=0;for(int i=0;i<3000;i++){native.step({});auto o=native.state().opponents->front();maxspeed=std::max(maxspeed,std::abs(o.speed));distance=std::max(distance,length(Vec{o.car[12]-initial[12],o.car[13]-initial[13],o.car[14]-initial[14]}));}for(size_t j=0;j<roster.size();++j){auto o=native.state().opponents->at(j);std::cout<<"native bot"<<j+1<<" position="<<o.car[12]<<","<<o.car[14]<<" speed="<<o.speed<<" recoveries="<<o.recovery_generation<<"\n";}std::cout<<"native first bot maxspeed="<<maxspeed<<" displacement="<<distance<<'\n';need(maxspeed>5&&distance>40,"native Forest1 bot makes sustained route progress in 30 seconds");}
 std::cout<<"race AI/shared Bullet tests passed\n";
 }catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
